using System;using System.Linq;using BeamScheduleFormatter;
class SlabEntryOptionsTests{static void Check(bool ok,string message){if(!ok)throw new Exception(message);}static void Main(){var slab=new SlabScheduleRow{Bars=new SlabBar[9]};for(int n=4;n<8;n++)slab.Bars[n]=new SlabBar{Diameter=10,SpacingMm=250};var typed=new[]{"5","2","0","2","0","3.5","4.5"};var elevated=SlabEntryOptions.Prepare("Elevated",typed,false,slab);Check(elevated[0]=="0"&&elevated[1]=="1"&&elevated[2]=="1"&&elevated[5]=="","Disabled ordinary inputs leaked into calculation");var gravel=SlabEntryOptions.Prepare("On gravel fill",typed,false,slab);Check(gravel.SequenceEqual(elevated),"Gravel retained stale cantilever-edge values");var cant=SlabEntryOptions.Prepare("Elevated / cantilever edge",typed,false,slab);Check(cant[0]=="5"&&cant[1]=="1"&&cant[5]=="","Cantilever changed unrelated reinforcement settings");var manual=SlabEntryOptions.Prepare("Elevated",typed,true,slab);Check(manual[0]=="0"&&manual[1]=="2"&&manual[5]=="3.5","Explicit reinforcement overrides lost");bool rejected=false;typed[1]="3";try{SlabEntryOptions.Prepare("Elevated",typed,true,slab);}catch(ArgumentException){rejected=true;}Check(rejected,"Invalid manual support count accepted");Console.WriteLine("PASS: context settings discard stale edge/optional values, preserve automatic steel and validate explicit overrides.");}}
